#include "station_directory.hpp"
#include <cassert>
#include <iostream>
using namespace qso;
int main(){StationDirectory d;d.remember("test1","N0CALL","BEACON TEST1 FN42 QSO73 v1.1.0",true,1792100000);d.remember("TEST2","N0CALL","BEACON TEST2 JN58AB QSO73 v1.1.0",true,1792100000);d.remember("QST","N0CALL");d.remember("N0CALL","N0CALL");assert(d.records.size()==2);d.records.at("TEST1").favorite=true;Json json(d.serialize());auto loaded=StationDirectory::parse(json);assert(loaded.records.at("TEST1").favorite&&loaded.records.at("TEST1").grid=="FN42"&&loaded.records.at("TEST1").lastHeard==1792100000);loaded.clear();assert(loaded.records.size()==1&&loaded.records.count("TEST1"));loaded.records.erase("TEST1");assert(loaded.records.empty());loaded.remember("TEST3","N0CALL","~Q73P:{\"k\":\"reply\",\"call\":\"TEST3\",\"grid\":\"AA00AA00\"}",true,1);assert(loaded.records.at("TEST3").grid=="AA00AA00");loaded.records.clear();assert(loaded.records.empty());try{Json bad("[{\"call\":\"TEST1\",\"grid\":\"ZZ99\"}]");StationDirectory::parse(bad);assert(false);}catch(const std::exception&){}std::cout<<"PASS: Windows directory roundtrip, favorite-preserving clear, individual delete, full reset, beacon/PING grid extraction and validation\n";}
